SELECT credential_id,symbol,exchange_order_id,strategy_id,strategy_instance_id,
       position_side,fill_role,position_cycle_key,exchange_side,client_order_id
FROM quant_strategy_order_intent
WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND exchange_order_id=#{orderId}

SELECT credential_id,symbol,client_order_id,strategy_id,strategy_instance_id,
       operation_type,position_side,exchange_side,position_cycle_key
FROM quant_strategy_pre_dispatch_intent
WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND client_order_id=#{clientOrderId}

mapper.insert:
INSERT INTO quant_strategy_order_intent
(credential_id,symbol,exchange_order_id,strategy_id,strategy_instance_id,
 position_side,fill_role,position_cycle_key,exchange_side,client_order_id,created_at)
SELECT credential_id,symbol,#{orderId},strategy_id,strategy_instance_id,
       position_side,operation_type,position_cycle_key,exchange_side,client_order_id,UTC_TIMESTAMP(6)
FROM quant_strategy_pre_dispatch_intent
WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND idempotency_key=#{key} AND client_order_id=#{clientOrderId}
  AND position_cycle_key IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM quant_order_dispatch_ticket t
    WHERE t.credential_id=#{credentialId}
      AND t.idempotency_key=#{key}
      AND t.symbol=#{symbol}
      AND t.client_order_id=#{clientOrderId}
      AND t.operation_type=quant_strategy_pre_dispatch_intent.operation_type
  )

mapper.update:
UPDATE quant_order
SET strategy_id=#{strategyId},strategy_instance_id=#{instanceId},
    position_side=#{positionSide},reduce_only=#{reduceOnly}
WHERE id=#{localId} AND credential_id=#{credentialId}
  AND symbol=#{symbol} AND exchange_order_id=#{orderId}
  AND client_order_id=#{clientOrderId}
  AND (strategy_id IS NULL OR strategy_id=#{strategyId})
  AND (strategy_instance_id IS NULL OR strategy_instance_id=#{instanceId})
  AND (position_side IS NULL OR position_side=#{positionSide})
  AND (reduce_only IS NULL OR reduce_only=#{reduceOnly})

mapper.select:
SELECT COUNT(*)
FROM quant_order
WHERE id=#{localId} AND credential_id=#{credentialId}
  AND symbol=#{symbol} AND exchange_order_id=#{orderId}
  AND client_order_id=#{clientOrderId}
  AND strategy_id=#{strategyId}
  AND strategy_instance_id=#{instanceId}
  AND position_side=#{positionSide}
  AND reduce_only=#{reduceOnly}

SELECT candidates.exchange_order_id
FROM (
    SELECT q.exchange_order_id
    FROM quant_strategy_order_intent i
    INNER JOIN quant_order q
        ON q.credential_id=i.credential_id
       AND q.symbol=i.symbol
       AND q.exchange_order_id=i.exchange_order_id
    WHERE i.credential_id=#{credentialId}
      AND i.symbol=#{symbol}
      AND i.strategy_instance_id=#{instanceId}
      AND i.position_cycle_key=#{positionCycleKey}
      AND i.position_side=#{positionSide}
      AND i.fill_role='CLOSE'
      AND i.exchange_side=#{exchangeSide}
      AND (q.strategy_instance_id IS NULL OR q.strategy_instance_id=#{instanceId})
      AND q.side=#{exchangeSide}
      AND (q.position_side IS NULL OR q.position_side IN (#{positionSide},'BOTH'))
      AND (q.reduce_only IS NULL OR q.reduce_only='1')
      AND (q.close_position IS NULL OR q.close_position<>'1')
      AND q.executed_quantity<=#{requestedQuantity}
      AND q.executed_quantity>0
      AND q.status IN ('FILLED','CANCELED','EXPIRED','REJECTED')
      AND q.updated_at>=UTC_TIMESTAMP(3)-INTERVAL 6 DAY

    UNION

    SELECT q.exchange_order_id
    FROM quant_strategy_pre_dispatch_intent p
    INNER JOIN quant_order q
        ON q.credential_id=p.credential_id
       AND q.symbol=p.symbol
       AND q.client_order_id=p.client_order_id
    WHERE p.credential_id=#{credentialId}
      AND p.symbol=#{symbol}
      AND p.strategy_instance_id=#{instanceId}
      AND p.position_cycle_key=#{positionCycleKey}
      AND p.position_side=#{positionSide}
      AND p.operation_type='CLOSE'
      AND p.exchange_side=#{exchangeSide}
      AND (q.strategy_instance_id IS NULL OR q.strategy_instance_id=#{instanceId})
      AND q.side=#{exchangeSide}
      AND (q.position_side IS NULL OR q.position_side IN (#{positionSide},'BOTH'))
      AND q.reduce_only='1'
      AND q.executed_quantity<=#{requestedQuantity}
      AND q.executed_quantity>0
      AND q.status IN ('FILLED','CANCELED','EXPIRED','REJECTED')
      AND q.updated_at>=UTC_TIMESTAMP(3)-INTERVAL 6 DAY
    UNION

    SELECT q.exchange_order_id
    FROM quant_protection_order p
    INNER JOIN quant_order q
        ON q.credential_id=p.credential_id
       AND q.symbol=p.symbol
       AND q.client_order_id=p.client_order_id
    WHERE p.credential_id=#{credentialId}
      AND p.symbol=#{symbol}
      AND p.strategy_instance_id=#{instanceId}
      AND p.position_cycle_key=#{positionCycleKey}
      AND p.position_side=#{positionSide}
      AND p.status='FINISHED'
      AND p.executed_quantity>0
      AND q.strategy_instance_id=#{instanceId}
      AND q.side=#{exchangeSide}
      AND (q.position_side IS NULL OR q.position_side IN (#{positionSide},'BOTH'))
      AND q.reduce_only='1'
      AND q.executed_quantity<=#{requestedQuantity}
      AND q.status IN ('FILLED','CANCELED','EXPIRED','REJECTED')
      AND q.updated_at>=UTC_TIMESTAMP(3)-INTERVAL 6 DAY

) candidates
WHERE candidates.exchange_order_id IS NOT NULL
